package net.zartra.gui;
import java.util.*;
final class VariableStore {enum Scope{GLOBAL,PLAYER,TEMP,SESSION}private final Map<String,String> global=new TreeMap<String,String>();private final Map<UUID,Map<String,String>> player=new HashMap<UUID,Map<String,String>>();private final Map<UUID,Map<String,Timed>> temporary=new HashMap<UUID,Map<String,Timed>>();private final Map<UUID,Map<String,String>> session=new HashMap<UUID,Map<String,String>>();
 static boolean validKey(String k){return k!=null&&k.matches("[a-zA-Z][a-zA-Z0-9_.-]{0,63}");}static boolean validValue(String v){return v!=null&&v.length()<=1024;}synchronized void setGlobal(String k,String v){set(global,k,v);}synchronized String global(String k){return global.get(k);}synchronized Map<String,String> globals(){return new TreeMap<String,String>(global);}synchronized void setPlayer(UUID id,String k,String v){set(map(player,id),k,v);}synchronized String player(UUID id,String k){Map<String,String> m=player.get(id);return m==null?null:m.get(k);}synchronized Map<UUID,Map<String,String>> players(){Map<UUID,Map<String,String>> out=new TreeMap<UUID,Map<String,String>>(new Comparator<UUID>(){public int compare(UUID a,UUID b){return a.toString().compareTo(b.toString());}});for(Map.Entry<UUID,Map<String,String>> e:player.entrySet())out.put(e.getKey(),new TreeMap<String,String>(e.getValue()));return out;}synchronized void setTemporary(UUID id,String k,String v,long ttl){if(v==null){map(temporary,id).remove(k);return;}if(!validKey(k)||!validValue(v))throw new IllegalArgumentException("invalid variable");map(temporary,id).put(k,new Timed(v,System.currentTimeMillis()+Math.max(1000,ttl)));}synchronized void setSession(UUID id,String menu,String k,String v){if(!validKey(k)||(v!=null&&!validValue(v)))throw new IllegalArgumentException("invalid variable");String composite=(menu==null?"":menu)+":"+k;Map<String,String> m=map(session,id);if(v==null)m.remove(composite);else m.put(composite,v);}synchronized void clearSession(UUID id){session.remove(id);}synchronized void purge(){long now=System.currentTimeMillis();for(Map<String,Timed> m:temporary.values())for(Iterator<Map.Entry<String,Timed>> it=m.entrySet().iterator();it.hasNext();)if(it.next().getValue().expires<now)it.remove();}
 synchronized String resolve(UUID id,String menu,String raw){if(raw==null)return null;String[] x=raw.split(":",2);Scope s=Scope.PLAYER;String key=raw;if(x.length==2)try{s=Scope.valueOf(x[0].toUpperCase());key=x[1];}catch(Exception ignored){}if(!validKey(key))return null;purge();if(s==Scope.GLOBAL)return global.get(key);if(s==Scope.PLAYER)return player(id,key);if(s==Scope.TEMP){Timed t=map(temporary,id).get(key);return t==null?null:t.value;}return map(session,id).get((menu==null?"":menu)+":"+key);}synchronized boolean apply(UUID id,String menu,String spec,String mode){String[] x=spec.split("\\|",3);if(x.length<2)return false;Scope s;try{s=Scope.valueOf(x[0].toUpperCase());}catch(Exception e){return false;}String key=x[1],value=x.length>2?x[2]:null;if(!validKey(key)||(value!=null&&!validValue(value)))return false;String current=resolve(id,menu,s.name()+":"+key);if("REMOVE".equals(mode))value=null;else if("TOGGLE".equals(mode))value=Boolean.toString(!Boolean.parseBoolean(current));else if("ADD".equals(mode))try{value=Double.toString(Double.parseDouble(current==null?"0":current)+Double.parseDouble(value));if(value.endsWith(".0"))value=value.substring(0,value.length()-2);}catch(Exception e){return false;}if(s==Scope.GLOBAL)setGlobal(key,value);else if(s==Scope.PLAYER)setPlayer(id,key,value);else if(s==Scope.TEMP)setTemporary(id,key,value,300000L);else setSession(id,menu,key,value);return true;}
 private static <T>Map<String,T> map(Map<UUID,Map<String,T>> all,UUID id){Map<String,T> m=all.get(id);if(m==null){m=new HashMap<String,T>();all.put(id,m);}return m;}private static void set(Map<String,String> m,String k,String v){if(!validKey(k)||(v!=null&&!validValue(v)))throw new IllegalArgumentException("invalid variable");if(v==null)m.remove(k);else m.put(k,v);}private static final class Timed{final String value;final long expires;Timed(String v,long e){value=v;expires=e;}}
}